int fn0(String tape) {
  int sum = 0;
  for (int i = 0; i + 1 < tape.length; i += 2) {
    int n = tape.codeUnitAt(i + 1) - 48;
    if (tape[i] == 'R') {
      sum += n * (i ~/ 2 + 1);
    } else if (tape[i] == 'E') {
      sum -= n * (i ~/ 2 + 1);
    } else if (n.isEven) {
      sum += 2;
    } else {
      sum -= 1;
    }
  }
  return sum;
}

