String fn0(int telemetry) {
  if ((telemetry & 0x01) == 0) {
    return 'Offline';
  }
  final int antennas = (telemetry >> 1) & 0x07;
  final int rssi = (telemetry >> 4) & 0x0F;
  final int score = rssi * antennas;

  if (score == 0) {
    return 'No Signal';
  } else if (score <= 15) {
    return 'Weak';
  } else if (score <= 45) {
    return 'Medium';
  } else {
    return 'Strong';
  }
}

