    int cut = logs[i].indexOf('|');
    int load = int.parse(cut == -1 ? logs[i] : logs[i].substring(0, cut));
    if (load > 450) {
      break;
    }
    if (logs[i].contains("drain")) {
      return i;
    }
  }
  return -1;
}

