Map<String, int> fn0(String manifest) {
  final result = <String, int>{};
  var state = 0;
  for (final rawLine in manifest.split('\n')) {
    final line = rawLine.trim();
    if (state == 0) {
      if (line == 'MANIFEST') state = 1;
    } else if (state == 1) {
      if (line == 'END') {
        state = 2;
      } else if (line.isNotEmpty && !line.startsWith('#')) {
        final parts = line.split(RegExp(r'\s+'));
        if (parts.length == 4 && parts[0] == 'CONTAINER') {
          final weight = int.tryParse(parts[2]);
          if (weight != null) {
            final dest = parts[3];
            result[dest] = (result[dest] ?? 0) + weight;
          }
        }
      }
    }
  }
  return result;
}

